// Lesson Plan Generator: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const PHASES = [['Starter', 0.10], ['Teach', 0.25], ['Guided practice', 0.25], ['Independent task', 0.25], ['Plenary & exit ticket', 0.15]];
return input.map(l => {
  const mins = PHASES.map(([, p]) => Math.round(l.minutes * p)); mins[mins.length - 1] += l.minutes - mins.reduce((a, b) => a + b, 0);
  const s0 = l.subtopics[0].toLowerCase(), sN = l.subtopics[l.subtopics.length - 1].toLowerCase(), t = l.topic.toLowerCase();
  const acts = { 'Starter': `Question on the board: 'Where have you seen ${t} in daily life?' Pairs share.`,
    'Teach': `Explain ${l.subtopics.join(', ')} with a worked example and a diagram.`,
    'Guided practice': `Class works through an example of ${s0} together; check with mini whiteboards.`,
    'Independent task': `Learners complete a short task applying ${sN}.`, 'Plenary & exit ticket': 'Learners answer the exit-ticket questions.' };
  const md = [`# ${l.subject}: ${l.topic}`, '', `**Class:** ${l.class} · **Duration:** ${l.minutes} minutes · **Week ${l.week}**`, '',
    '## Objectives', '', `1. Identify the key terms in ${t}`, `2. Explain how ${s0} works using an example`, `3. Design a simple ${sN} for a real problem`, '',
    '## Lesson sequence', '', '| Phase | Minutes | Activity |', '|---|---:|---|', ...PHASES.map(([n], i) => `| ${n} | ${mins[i]} | ${acts[n]} |`), '',
    '## Differentiation', '', `- Support: worked example and sentence starters for ${s0}.`, `- Stretch: compare two approaches to ${sN} and justify the better one.`, '',
    '## Resources', '', '- ' + l.resources.join(', '), '', '## Exit ticket', '', `- What is ${s0}?`, `- Give one real example of ${t}.`, '- What are you still unsure about?'].join('\n');
  return { json: { class: l.class, topic: l.topic, minutes_check: mins.reduce((a, b) => a + b, 0), lesson_note: md } };
});
